-rw-r--r-- 1 root root 2151 Aug 23 20:37 /workspace/projection_diagnostic.py
import math
import sys


def read_atoms(path):
    atoms = []
    ca = []
    with open(path, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            if not (line.startswith("ATOM  ") or line.startswith("HETATM")):
                continue
            try:
                xyz = (float(line[30:38]), float(line[38:46]), float(line[46:54]))
            except ValueError:
                continue
            atoms.append(xyz)
            if line[12:16].strip() == "CA":
                ca.append(xyz)
    return atoms, ca

